    private class Part(val d: String, val stroke: Float = 0f, val alpha: Float = 1f, val evenOdd: Boolean = false)

    private fun F(d: String, alpha: Float = 1f, evenOdd: Boolean = false) = Part(d, alpha = alpha, evenOdd = evenOdd)
    private fun S(d: String, width: Float) = Part(d, stroke = width)

    private fun vector(name: String, w: Float, h: Float, vararg parts: Part): ImageVector {
        val b = ImageVector.Builder(name = name, defaultWidth = w.dp, defaultHeight = h.dp, viewportWidth = w, viewportHeight = h)
        for (p in parts) {
            if (p.stroke > 0f) {
                b.addPath(
                    pathData = addPathNodes(p.d),
                    stroke = SolidColor(Color.Black),
                    strokeLineWidth = p.stroke,
                    strokeLineCap = StrokeCap.Round,
                    strokeLineJoin = StrokeJoin.Round,
                )
            } else {
                b.addPath(
                    pathData = addPathNodes(p.d),
                    fill = SolidColor(Color.Black),
                    fillAlpha = p.alpha,
                    pathFillType = if (p.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                )
            }
        }
        return b.build()
    }
}
